// Extract AI JSON output from Vision or Text Parser
const rawOutput = $input.first().json.message?.content || $input.first().json.text || "{}";

let parsed = {};
try {
  const cleanJson = rawOutput.replace(/```json/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    is_valid_expense: false,
    needs_clarification: true,
    clarification_question: "Could not parse expense details. Please provide the merchant name and amount in JPY (e.g. 'Ramen 1200 JPY cash')."
  };
}

// Get chat info from trigger
const triggerData = $("Telegram Trigger").first().json;
const chatId = triggerData.message?.chat?.id || triggerData.message?.from?.id;
const messageId = triggerData.message?.message_id;

// Exchange rate: 1 PHP ≈ 2.70 JPY
const fxRate = 2.70;
const amountJPY = parseInt(parsed.amount, 10) || 0;
const amountPHP = Math.round(amountJPY / fxRate);

// TravelTokyo Schema Compatible Expense Record
const expenseRecord = {
  id: `paid-${Date.now()}`,
  title: parsed.title || "Tokyo Expense",
  amount: amountJPY,
  currency: "JPY",
  category: parsed.category || "food",
  paymentMethod: parsed.paymentMethod || "Cash",
  date: parsed.date || new Date().toISOString().split('T')[0],
  status: "paid",
  notes: parsed.notes || "Logged via Telegram receipt bot",
  convertedAmountPHP: amountPHP,
  chatId: chatId,
  messageId: messageId,
  needs_clarification: parsed.needs_clarification || false,
  clarification_question: parsed.clarification_question || ""
};

return [ { json: expenseRecord } ];

